import json,pathlib
for name in ['bugfix','chore','feature','investigate','refactor']:
 r=pathlib.Path('workflow-evaluation/runs')/(name+'-base-001')
 print(name)
 for f in sorted((r/'transcript').glob('page-*.json')):
  d=json.load(open(f))['data']; print(f.name, list(d), {k:v for k,v in d.items() if k!='messages'})
  if 'messages' in d:
   for m in d['messages']:
    extra={k:v for k,v in m.items() if k not in ['content','toolCalls','id','ordinal','role','toolName','toolCallId']}
    if any(v not in (False,None,[],{}) for v in extra.values()):print('message extra',m.get('ordinal'),extra)
 if name=='bugfix':print(next(r.glob('capture-*')).joinpath('status.json').read_text())
PY","timeout":10}

